create table if not exists student_course_requests(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),student_id uuid not null references students(id) on delete cascade,course_id uuid not null references course_catalog(id),priority smallint not null default 100,request_kind text not null default 'PRIMARY' check(request_kind in('PRIMARY','ALTERNATIVE','SUBSTITUTE')),alternative_group text,allow_overlap boolean not null default false,active boolean not null default true,source text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_student_course_requests_solver on student_course_requests(institution_code,active,student_id,priority);
create table if not exists student_free_time_requests(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),student_id uuid not null references students(id) on delete cascade,weekday smallint not null check(weekday between 1 and 7),periods smallint[] not null,mode text not null default 'SOFT' check(mode in('HARD','MEDIUM','SOFT','OFF')),weight numeric not null default 1 check(weight>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_student_free_time_solver on student_free_time_requests(institution_code,active,student_id,weekday);
create table if not exists student_schedule_enrollments(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),student_id uuid not null references students(id) on delete cascade,teacher_assignment_id uuid not null references teacher_course_assignments(id) on delete cascade,locked boolean not null default false,source text not null default 'solver',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_code,student_id,teacher_assignment_id));
create index if not exists idx_student_schedule_enrollments_solver on student_schedule_enrollments(institution_code,active,student_id);
alter table student_course_requests enable row level security;alter table student_free_time_requests enable row level security;alter table student_schedule_enrollments enable row level security;
drop policy if exists student_course_requests_read on student_course_requests;create policy student_course_requests_read on student_course_requests for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists student_course_requests_manage on student_course_requests;create policy student_course_requests_manage on student_course_requests for all to authenticated using((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
drop policy if exists student_free_time_requests_read on student_free_time_requests;create policy student_free_time_requests_read on student_free_time_requests for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists student_free_time_requests_manage on student_free_time_requests;create policy student_free_time_requests_manage on student_free_time_requests for all to authenticated using((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
drop policy if exists student_schedule_enrollments_read on student_schedule_enrollments;create policy student_schedule_enrollments_read on student_schedule_enrollments for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists student_schedule_enrollments_manage on student_schedule_enrollments;create policy student_schedule_enrollments_manage on student_schedule_enrollments for all to authenticated using((has_permission('schedule.generate') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.generate') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code));